/**
 * SERVICE × COUNTY landing pages — /locations/[county]/[service]/
 *
 * These are deliberately NOT templated. The 26 county pages share one layout
 * and roughly 120 unique words each, which is the doorway-page pattern Google
 * suppresses; that is why /locations/limerick/ is indexed but nowhere on page
 * one. Every page in this file is written from scratch for one service in one
 * county, and none of it is generated by string interpolation.
 *
 * Add a county only when there is genuinely something specific to say about
 * it. Three real pages beat thirty spun ones.
 */

export interface ServicePage {
  county: string;
  countySlug: string;
  service: string;
  serviceSlug: string;
  title: string;
  description: string;
  h1: string;
  /** Opening — establishes local knowledge before it sells anything. */
  intro: string[];
  sections: {
    heading: string;
    body: string[];
    /** Optional bulleted detail under the prose. */
    list?: { title: string; body: string }[];
  }[];
  areas: { heading: string; body: string; towns: string[] };
  pricing: { heading: string; body: string[] };
  faqs: { q: string; a: string }[];
  related: { label: string; href: string }[];
}

