export const servicePageBy = (countySlug: string, serviceSlug: string) =>
  servicePages.find(
    (p) => p.countySlug === countySlug && p.serviceSlug === serviceSlug,
  );

export const servicePagesForCounty = (countySlug: string) =>
  servicePages.filter((p) => p.countySlug === countySlug);
